  if(!validMonths||!days.length||days.length>15000||!days.every(([d,v])=>goodDay(d)&&Array.isArray(v)&&v.length===3&&spendingCentsOk(v[0])&&v.slice(1).every(c=>c===null||Number.isSafeInteger(c)))||typeof body.source!=='string'||body.source.length>240)return err('消費日期或每日簽帳彙總格式不正確。',400);
  if(groupDays&&(!Array.isArray(groupDays)||groupDays.length!==days.length||groupDays.length>15000||!groupDays.every(([day,vals])=>goodDay(day)&&Array.isArray(vals)&&vals.length===3&&vals.every(spendingCentsOk)&&JSON.stringify(days.find(([d])=>d===day)?.[1]?.[0])===JSON.stringify(vals.reduce((a,b)=>a+b,0)))))return err('每日消費地點分類與金額不一致。',400);
