  if(byMonth.size!==entries.length||entries.some(([m,r])=>!byMonth.has(m)||r.reduce((a,b)=>a+b[1],0)!==byMonth.get(m)))return err('每月消費合計與每日簽帳金額不一致，已取消匯入。',400);
  const months={...current.months}, daily={...(current.daily||{})},dailyGroups={...(current.dailyGroups||{})}, replace=new Set(entries.map(([m])=>m));
  for(const [d] of Object.entries(daily))if(replace.has(d.slice(0,4)+d.slice(5,7)))delete daily[d];
