// Compare the actual server-side source rows, not only the last imported hash.
// Stable imported IDs keep user edits and the highlight-marker table intact.
const budgetRowFields=['kind','code','category','status','cat','catExplicit','bu','label','seller','buyer','period','date','settle','inv','amount','grossMissing','untaxed','tax','handler','noInvoiceReason','usd','fx','note'];
const budgetGroupKey=a=>a.code+'/'+a.kind;
const budgetRowValue=(r,k)=>r[k]===undefined?(['untaxed','tax','usd','fx'].includes(k)?null:k==='grossMissing'?0:k==='catExplicit'?1:''):r[k];
const budgetRowSignature=r=>JSON.stringify(budgetRowFields.map(k=>budgetRowValue(r,k)));
const budgetPosition=r=>typeof r.src==='string'&&r.src&&Number.isInteger(r.row)&&r.row>=2?JSON.stringify([r.src,r.row]):null;
function budgetWorkbookPlan(ledger,changes,markIds,incoming){
 const groups=new Map();
 for(const r of incoming){const k=budgetGroupKey(r);if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r);}
 const marks=new Set(markIds);
 const byGroup=new Map();
 const stats={groups:groups.size,added:0,updated:0,removed:0,unchanged:0,preservedEdits:0,preservedMarks:0,conflicts:0};
 const groupStats=[];
 for(const [key,rows] of groups){
  const previous=ledger.filter(r=>budgetGroupKey(r)===key&&!String(r.id).startsWith('local-'));
  const unclaimed=new Set(previous.map((_,i)=>i));
  const matches=new Array(rows.length).fill(-1);
  const signatures=previous.map(budgetRowSignature),positions=previous.map(budgetPosition);
  const incomingSigs=rows.map(budgetRowSignature),incomingPos=rows.map(budgetPosition);
  // 1. Identical source position and data.
  for(let i=0;i<rows.length;i++){
   if(!incomingPos[i])continue;
   const j=previous.findIndex((old,k)=>unclaimed.has(k)&&positions[k]===incomingPos[i]&&signatures[k]===incomingSigs[i]);
   if(j!==-1){matches[i]=j;unclaimed.delete(j);}
  }
  // 2. Identical contents, even when Excel rows moved. Prefer modified/marked IDs.
  for(let i=0;i<rows.length;i++){
   if(matches[i]!==-1)continue;
   const candidates=[...unclaimed].filter(j=>signatures[j]===incomingSigs[i]);
   candidates.sort((a,b)=>Number(Boolean(changes[previous[b].id]||marks.has(previous[b].id)))-Number(Boolean(changes[previous[a].id]||marks.has(previous[a].id))));
   if(candidates.length){const j=candidates[0];matches[i]=j;unclaimed.delete(j);}
  }
  // 3. Changed contents in the same source row. Never use the hash to skip them.
  for(let i=0;i<rows.length;i++){
   if(matches[i]!==-1||!incomingPos[i])continue;
   const j=previous.findIndex((old,k)=>unclaimed.has(k)&&positions[k]===incomingPos[i]);
   if(j!==-1){matches[i]=j;unclaimed.delete(j);}
  }
  const result=[],one={group:key,added:0,updated:0,removed:0,unchanged:0,preservedEdits:0,preservedMarks:0,conflicts:0};
  for(let i=0;i<rows.length;i++){
   const old=matches[i]<0?null:previous[matches[i]],row=rows[i];
   if(!old){one.added++;result.push({...row,id:null});continue;}
   const changed=signatures[matches[i]]!==incomingSigs[i];
   if(changed)one.updated++;else one.unchanged++;
   if(Object.hasOwn(changes,old.id))one.preservedEdits++;
   if(marks.has(old.id))one.preservedMarks++;
   result.push({...row,id:old.id,flag:!row.noInvoiceReason&&(!row.inv||!row.date)&&['已開發票','已請款','已驗收'].includes(row.status)?'原表發票資訊不全／無獨立發票':''});
  }
  one.removed=unclaimed.size;
  for(const j of unclaimed){const id=previous[j].id;if(Object.hasOwn(changes,id)||marks.has(id))one.conflicts++;}
  for(const k of ['added','updated','removed','unchanged','preservedEdits','preservedMarks','conflicts'])stats[k]+=one[k];
  groupStats.push(one);byGroup.set(key,result);
 }
 return {stats,groupStats,byGroup,unchanged:stats.added+stats.updated+stats.removed===0};
}

